import 'dart:async'; import 'package:flutter/material.dart'; import '../database/db_helper.dart'; import '../models/book.dart'; import '../models/study_session.dart'; import 'package:intl/intl.dart';
class TimerScreen extends StatefulWidget{const TimerScreen({super.key});@override State<TimerScreen> createState()=>_TimerScreenState();}
class _TimerScreenState extends State<TimerScreen>{DateTime? started;Timer? tick;int elapsed=0;List<Book> books=[];int? selected;@override void initState(){super.initState();DbHelper.instance.getBooks().then((v){if(mounted)setState(()=>books=v);});}String clock(int n)=>'${(n~/3600).toString().padLeft(2,'0')}:${((n%3600)~/60).toString().padLeft(2,'0')}:${(n%60).toString().padLeft(2,'0')}';void start(){started=DateTime.now();tick=Timer.periodic(const Duration(seconds:1),(_){if(mounted)setState(()=>elapsed=DateTime.now().difference(started!).inSeconds);});setState((){});}Future<void> stop()async{if(started==null)return;tick?.cancel();final end=DateTime.now();final b=books.where((x)=>x.id==selected).firstOrNull;await DbHelper.instance.createSession(StudySession(bookId:selected,bookTitle:b?.title,startAt:started!,endAt:end));if(!mounted)return;ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('نشست ${DateFormat('HH:mm:ss').format(started!)} تا ${DateFormat('HH:mm:ss').format(end)} ذخیره شد')));setState((){started=null;elapsed=0;});}@override void dispose(){tick?.cancel();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('زمان‌سنج مطالعه')),body:Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[const Icon(Icons.hourglass_bottom,size:54,color:Color(0xff176b52)),const SizedBox(height:18),Text(clock(elapsed),style:const TextStyle(fontSize:48,fontWeight:FontWeight.w700,fontFeatures:[])),if(started!=null)Text('شروع دقیق: ${DateFormat('yyyy/MM/dd  HH:mm:ss').format(started!)}'),const SizedBox(height:25),DropdownButtonFormField<int?>(value:selected,decoration:const InputDecoration(labelText:'کتاب (اختیاری)',border:OutlineInputBorder()),items:[const DropdownMenuItem<int?>(value:null,child:Text('بدون انتخاب')), ...books.map((b)=>DropdownMenuItem<int?>(value:b.id,child:Text(b.title)))],onChanged:started==null?(v)=>setState(()=>selected=v):null),const SizedBox(height:20),FilledButton.icon(onPressed:started==null?start:stop,icon:Icon(started==null?Icons.play_arrow:Icons.stop),label:Text(started==null?'شروع مطالعه':'پایان و ذخیره'))]))));}
extension FirstOrNull<E> on Iterable<E>{E? get firstOrNull=>isEmpty?null:first;}
